"""Offline execution of the JavaScript generated by TerminalAppTransport.move_created_tab."""

import asyncio
import json
import shutil
import subprocess

import pytest

from kirabridge.platform_adapters.terminal_app import TerminalAppTransport

RECEIPT = {
    "window_id": 12601,
    "tty": "/dev/ttys014",
    "nonce": "KiraBridge_test_nonce",
    "app_pid": 4321,
    "app_identity": "501 ?? Thu Nov 13 10:00:00 2026 1 /Terminal",
}


def _offline_harness(source: str, change: str | None) -> str:
    config = json.dumps({"source": source, "change": change})
    return (
        "const cfg="
        + config
        + ";const vm=require('node:vm');"
        + r"""
let clicks=0, selectedCalls=0, windowCalls=0, nameCalls=0, enabledCalls=0;
const nonce='KiraBridge_test_nonce', tty='/dev/ttys014';
const tab={tty:()=>tty};
const targetWindow={id:()=>12601,tabs:()=>[tab],selectedTab:()=>tab,name:()=>nonce};
const app={windows:()=>[targetWindow]};
function checkTargetIdentity(){}
function checkCreatedTab(){checkTargetIdentity();if(targetWindow.tabs().length!==1||
 app.windows().flatMap(w=>w.tabs()).filter(t=>t.tty()==='/dev/ttys014').length!==1||
 !targetWindow.name().includes('KiraBridge_test_nonce'))
 throw Error('Created terminal identity changed');}
const detach={
 name:()=>{nameCalls++;return cfg.change==='late-label'&&nameCalls>1
  ?'Other':'Tab in ein neues Fenster bewegen';},
 enabled:()=>{enabledCalls++;return !(cfg.change==='late-disabled'&&enabledCalls>1);},
 click:()=>{clicks++;}
};
const menu={name:()=> 'Fenster',menus:()=>[{menuItems:()=>[detach]}]};
const owner={
 frontmost:()=>!(cfg.change==='late-focus'&&++selectedCalls>1),
 windows:()=>{windowCalls++;return [{name:()=>cfg.change==='late-title'&&windowCalls>1
  ?'changed':nonce}];},
 menuBars:()=>[{menuBarItems:()=>[menu]}]
};
const systemEvents={processes:()=>[{unixId:()=>4321,
 bundleIdentifier:()=> 'com.apple.Terminal',...owner}]};
function Application(name){return name==='System Events'?systemEvents:app;}
let error;
try{vm.runInNewContext(cfg.source,{Application});}catch(e){error=e.message;}
process.stdout.write(JSON.stringify({clicks,error}));
"""
    )


async def _capture_actual_source() -> str:
    captured = []

    async def native(self, source, *, mutation):
        assert mutation is True
        captured.append(source)
        return {"detached": True}

    transport = type(
        "FakeTransport",
        (),
        {
            "created_tab_guard": lambda self, receipt: (
                "const app=Application('Terminal');"
                "const targetWindow={id:()=>12601,tabs:()=>[{tty:()=>'/dev/ttys014'}],"
                "selectedTab:()=>({tty:()=>'/dev/ttys014'}),"
                "name:()=> 'KiraBridge_test_nonce'};"
                "function checkTargetIdentity(){};"
                "function checkCreatedTab(){checkTargetIdentity();"
                "if(targetWindow.tabs().length!==1||"
                "app.windows().flatMap(w=>w.tabs()).filter(t=>t.tty()==='/dev/ttys014').length!==1||"
                "!targetWindow.name().includes('KiraBridge_test_nonce'))"
                "throw Error('Created terminal identity changed');}"
            ),
            "native": native,
        },
    )()
    await TerminalAppTransport.move_created_tab(transport, RECEIPT)
    assert len(captured) == 1
    return captured[0]


@pytest.mark.parametrize(
    ("change", "expected_error"),
    [
        ("late-focus", "Detach target focus changed"),
        ("late-title", "Detach target title changed"),
        ("late-label", "Detach target menu label changed"),
        ("late-disabled", "Detach target menu disabled"),
        (None, None),
    ],
)
@pytest.mark.asyncio
async def test_actual_detach_generator_rechecks_late_state_before_click(change, expected_error):
    node = shutil.which("node")
    if node is None:
        pytest.skip("Node.js runtime unavailable")

    source = await _capture_actual_source()

    completed = await asyncio.to_thread(
        subprocess.run,
        [node, "-e", _offline_harness(source, change)],
        check=True,
        capture_output=True,
        text=True,
        timeout=3,
    )
    observed = json.loads(completed.stdout)
    assert observed["clicks"] == (1 if expected_error is None else 0)
    if expected_error is None:
        assert observed.get("error") is None
    else:
        assert observed["error"] == expected_error
